def prime_factorization(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

print(f"Factorization of 39455: {prime_factorization(39455)}")
print(f"Factorization of 94175: {prime_factorization(94175)}")
